"""train_branched_3l.py -- GENERATED by q2_threelevel.py. Do not edit by hand.

The published train() with exactly two changes, each asserted to match once at generation time:

  1. the network is built with branch_sizes=[4, 3] instead of the default [3, 3];
  2. the epsilon-greedy random action draws the reliability branch from range(4), not range(3).

(2) is the one that matters and the one that is easy to miss. The published line is
        a = [random.randint(0, 2), random.randint(0, 2)]
with the bound hard-coded. Enlarge the network without enlarging that draw and MID is never
explored during the epsilon phase -- it can then only ever be reached greedily, by a head that has
no experience of it. The campaign would run to completion, the agent would not use MID, and the
paper would report that the cliff makes intermediate powers poor value. That conclusion would be an
artefact of an exploration bound, and nothing in the output would look wrong.

BranchedEnv6G is rebound to the three-level subclass, so both the initial construction and the
episode-boundary rebuild inside train() -- and the one resumable_train.py inserts into its restore
block -- all build the three-level environment.
"""
from train_branched_nyu import *                      # noqa: F401,F403  (published trainer)
import train_branched_nyu as _PUB
from q2_threelevel import build_env_class, BRANCH_SIZES_3L

BranchedEnv6G = build_env_class()[0]                  # override AFTER the star import

def train(seed, binary_power, out, slow, med, steps=STEPS, guard_db=None, guard_mode='state'):
    set_seed(seed); pool = slow + med
    online, target = build_branched_networks(OBS_DIM, branch_sizes=BRANCH_SIZES_3L)
    opt = optim.Adam(online.parameters(), lr=3e-4)
    buf = NStepPERBuffer(500_000, n_steps=NSTEP, gamma=GAMMA, alpha=ALPHA)
    rng = np.random.default_rng(seed)
    smp = lambda stg: (slow if stg == "SLOW" else pool)[rng.integers(len(slow if stg == "SLOW" else pool))]
    stage = "SLOW"; env = BranchedEnv6G(smp(stage), binary_power=binary_power, guard_db=guard_db, guard_mode=guard_mode); obs, _ = env.reset()
    epr = deque(maxlen=20); er = 0.0; best = -1e18; saved = False
    def _save(): save_branched(online, out, {'seed': seed, 'binary_power': binary_power, 'training_mode': 'nyu_ci_reliability_tilt'})
    for step in range(1, steps + 1):
        frac = step / steps; stage = "SLOW" if frac < STAGE_SLOW_END else "SLOW+MED"
        eps = epsilon_schedule(step, EPS_START, EPS_END, EPS_FRACTION, steps); beta = beta_schedule(step, PER_BETA0, PER_BETA1, steps)
        if random.random() < eps:
            a = [random.randint(0, BRANCH_SIZES_3L[0] - 1), random.randint(0, BRANCH_SIZES_3L[1] - 1)]
        else:
            a = online.act(obs)
        nobs, r, term, trunc, info = env.step(a); done = term or trunc; er += r
        buf.add(obs, a, r, nobs, term); obs = nobs
        if done:
            epr.append(er); er = 0.0; env = BranchedEnv6G(smp(stage), binary_power=binary_power, guard_db=guard_db, guard_mode=guard_mode); obs, _ = env.reset()
            if frac > EPS_FRACTION and len(epr) == epr.maxlen:
                m = float(np.mean(epr))
                if m > best: best = m; _save(); saved = True
        if step >= LEARNING_STARTS and step % TRAIN_FREQ == 0 and len(buf) >= BATCH:
            ib, wb, ob, ab, rb, nb, db = buf.sample(BATCH, beta)
            loss, td = branched_td_loss(online, target, ob, ab, rb, nb, db, wb, gamma_n=GAMMA ** NSTEP)
            opt.zero_grad(); loss.backward(); nn.utils.clip_grad_norm_(online.parameters(), 10.0); opt.step()
            buf.update_priorities(ib, td)
        if step % TARGET_UPDATE == 0: polyak_update(online, target, TAU)
    if not saved: _save()
